solution.solution.cpp:
#include <cstdint>
#include <optional>
#include <string>
#include <vector>

struct Ipv4
{
    std::uint8_t headerLength;
    std::uint16_t totalLength;
    std::uint16_t id;
    bool dontFragment;
    bool moreFragments;
    std::uint16_t fragmentOffset;
    std::uint8_t ttl;
    std::uint8_t protocol;
    std::uint32_t source;
    std::uint32_t destination;
    bool checksumOk;
};

namespace
{
    std::uint16_t be16(const std::vector<std::uint8_t>& b, std::size_t i)
    {
        return static_cast<std::uint16_t>((b[i] << 8) | b[i + 1]);
    }

    std::uint32_t be32(const std::vector<std::uint8_t>& b, std::size_t i)
    {
        return (std::uint32_t{ be16(b, i) } << 16) | be16(b, i + 2);
    }

    std::uint16_t checksum(const std::vector<std::uint8_t>& b, std::size_t length)
    {
        std::uint32_t sum{ 0 };
        for (std::size_t i{ 0 }; i < length; i += 2)
        {
            sum += (std::uint32_t{ b[i] } << 8) | (i + 1 < length ? b[i + 1] : 0u);
            sum = (sum & 0xFFFF) + (sum >> 16);
        }
        return static_cast<std::uint16_t>(~sum & 0xFFFF);
    }
}

std::string macToString(const std::vector<std::uint8_t>& frame, std::size_t offset)
{
    if (offset > frame.size() || frame.size() - offset < 6) return "";
    const char* digits{ "0123456789abcdef" };
    std::string s;
    for (std::size_t i{ 0 }; i < 6; ++i)
    {
        if (i > 0) s += ':';
        s += digits[frame[offset + i] >> 4];
        s += digits[frame[offset + i] & 0x0F];
    }
    return s;
}

std::string ipToString(std::uint32_t ip)
{
    return std::to_string(ip >> 24) + '.' + std::to_string((ip >> 16) & 0xFF) + '.'
         + std::to_string((ip >> 8) & 0xFF) + '.' + std::to_string(ip & 0xFF);
}

std::optional<std::uint16_t> etherType(const std::vector<std::uint8_t>& frame, std::size_t& payloadOffset)
{
    if (frame.size() < 14) return std::nullopt;
    std::uint16_t type{ be16(frame, 12) };
    payloadOffset = 14;
    if (type == 0x8100)
    {
        if (frame.size() < 18) return std::nullopt;
        type = be16(frame, 16);
        payloadOffset = 18;
    }
    return type;
}

std::optional<Ipv4> parseIpv4(const std::vector<std::uint8_t>& p)
{
    if (p.size() < 20 || (p[0] >> 4) != 4) return std::nullopt;
    Ipv4 h{};
    h.headerLength = static_cast<std::uint8_t>((p[0] & 0x0F) * 4);
    if (h.headerLength < 20 || h.headerLength > p.size()) return std::nullopt;
    h.totalLength = be16(p, 2);
    if (h.totalLength < h.headerLength || h.totalLength > p.size()) return std::nullopt;
    h.id = be16(p, 4);
    const std::uint16_t fragment{ be16(p, 6) };
    h.dontFragment = (fragment & 0x4000) != 0;
    h.moreFragments = (fragment & 0x2000) != 0;
    h.fragmentOffset = static_cast<std::uint16_t>((fragment & 0x1FFF) * 8);
    h.ttl = p[8];
    h.protocol = p[9];
    h.source = be32(p, 12);
    h.destination = be32(p, 16);
    h.checksumOk = checksum(p, h.headerLength) == 0;
    return h;
}

unitTests:
using Bytes = std::vector<std::uint8_t>;
Bytes sampleIp() {
    Bytes p{ 0x45, 0x00, 0x00, 0x73, 0x00, 0x00, 0x40, 0x00, 0x40, 0x11, 0xB8, 0x61,
             0xC0, 0xA8, 0x00, 0x01, 0xC0, 0xA8, 0x00, 0xC7 };
    p.resize(0x73, 0);
    return p;
}
TEST("addresses as text") {
    const Bytes f{ 0x3C, 0x22, 0xFB, 0x12, 0x9A, 0x01, 0, 0, 0, 0, 0, 0xFF };
    CHECK_EQ(macToString(f, 0), std::string("3c:22:fb:12:9a:01"));
    CHECK_EQ(macToString(f, 6), std::string("00:00:00:00:00:ff"));
    CHECK_EQ(macToString(f, 7), std::string(""));
    CHECK_EQ(ipToString(0xC0A80001), std::string("192.168.0.1"));
    CHECK_EQ(ipToString(0), std::string("0.0.0.0"));
    CHECK_EQ(ipToString(0xFFFFFFFF), std::string("255.255.255.255"));
}
TEST("EtherType and VLAN tags") {
    Bytes f(14, 0); f[12] = 0x08; f[13] = 0x00;
    std::size_t at{ 0 };
    CHECK(etherType(f, at) == std::optional<std::uint16_t>{ 0x0800 });
    CHECK_EQ(at, 14u);
    Bytes v(18, 0); v[12] = 0x81; v[13] = 0x00; v[14] = 0x00; v[15] = 0x05; v[16] = 0x86; v[17] = 0xDD;
    CHECK(etherType(v, at) == std::optional<std::uint16_t>{ 0x86DD });
    CHECK_EQ(at, 18u);
    v.pop_back();
    CHECK(!etherType(v, at).has_value());
    CHECK(!etherType(Bytes(13, 0), at).has_value());
}
TEST("a real IPv4 header") {
    const auto h{ parseIpv4(sampleIp()) };
    CHECK(h.has_value());
    if (h) {
        CHECK_EQ(h->headerLength, 20);
        CHECK_EQ(h->totalLength, 115);
        CHECK(h->dontFragment);
        CHECK(!h->moreFragments);
        CHECK_EQ(h->fragmentOffset, 0);
        CHECK_EQ(h->ttl, 64);
        CHECK_EQ(h->protocol, 17);
        CHECK_EQ(h->source, 0xC0A80001u);
        CHECK_EQ(h->destination, 0xC0A800C7u);
        CHECK(h->checksumOk);
    }
    Bytes changed{ sampleIp() }; changed[8] = 63;
    const auto bad{ parseIpv4(changed) };
    CHECK(bad.has_value() && !bad->checksumOk);
    Bytes padded{ sampleIp() }; padded.resize(padded.size() + 5, 0);
    const auto pad{ parseIpv4(padded) };
    CHECK(pad.has_value() && pad->totalLength == 115);
}
TEST("options and fragments") {
    Bytes o(24, 0); o[0] = 0x46; o[3] = 24; o[9] = 6;
    const auto withOptions{ parseIpv4(o) };
    CHECK(withOptions.has_value() && withOptions->headerLength == 24);
    Bytes f{ sampleIp() }; f[6] = 0x20; f[7] = 0x05;
    const auto fragment{ parseIpv4(f) };
    CHECK(fragment.has_value());
    if (fragment) { CHECK(fragment->moreFragments); CHECK(!fragment->dontFragment); CHECK_EQ(fragment->fragmentOffset, 40); }
}
TEST("rejected headers") {
    Bytes v6{ sampleIp() }; v6[0] = 0x65;
    CHECK(!parseIpv4(v6).has_value());
    Bytes ihl{ sampleIp() }; ihl[0] = 0x44;
    CHECK(!parseIpv4(ihl).has_value());
    Bytes huge{ sampleIp() }; huge[0] = 0x4F; huge.resize(40);
    huge[2] = 0; huge[3] = 40;
    CHECK(!parseIpv4(huge).has_value());
    Bytes cut{ sampleIp() }; cut.pop_back();
    CHECK(!parseIpv4(cut).has_value());
    Bytes small{ sampleIp() }; small[2] = 0; small[3] = 19;
    CHECK(!parseIpv4(small).has_value());
    CHECK(!parseIpv4(Bytes(19, 0x45)).has_value());
}

